                            .text_color(p.on_primary)
                            .cursor_pointer()
                            .child(tr(cx, "Turn into rules", "生成路由规则")),
                        cx,
                        move |this, _, cx| {
                            cx.emit(AiChatSpendEvent::ApplyPlan {
                                monthly_savings: monthly_save,
                            });
                            this.toast = Some((
                                tr(
                                    cx,
                                    "Staged 3 routing rules in model-routing.toml",
                                    "已生成 3 条模型路由规则",
